<?php

declare(strict_types=1);

namespace Atannex\LaravelFlutterBridge\Console;

use Atannex\LaravelFlutterBridge\Broadcasting\BroadcastGate;
use Atannex\LaravelFlutterBridge\Services\FlutterAppManager;
use Illuminate\Console\Command;
use Illuminate\Support\Str;

class ExportConfigCommand extends Command
{
    /**
     * Generated file name.
     */
    public const FILE_NAME = 'laravel_bridge_config.g.dart';

    /**
     * The name and signature of the console command.
     */
    protected $signature = 'flutter:export-config
                            {--base-url= : Public base URL of this server (default: app.url)}
                            {--app-key= : App key to embed (see flutter:app:create)}
                            {--output= : Destination file or directory}';

    /**
     * The console command description.
     */
    protected $description = 'Generate a Dart LaravelConnection config (laravel_bridge_config.g.dart) for the Flutter client';

    /**
     * Execute the console command.
     */
    public function handle(FlutterAppManager $apps): int
    {
        $baseUrl = rtrim((string) ($this->option('base-url') ?: config('app.url', 'http://localhost')), '/');
        $appKey = $this->option('app-key') ?: null;

        if ($appKey !== null) {
            $app = $apps->findByKey((string) $appKey);

            if ($app === null) {
                $this->error("App key [{$appKey}] is not registered. Create one with flutter:app:create.");

                return self::FAILURE;
            }

            if ($app->isSuspended()) {
                $this->warn("App \"{$app->name}\" is suspended; clients using this key will be rejected.");
            }
        } elseif (config('flutter-bridge.connections.require_app_key', false)) {
            $this->warn('connections.require_app_key is enabled but no --app-key was given.');
        }

        $outputPath = $this->resolveOutputPath();
        $directory = dirname($outputPath);

        if (! is_dir($directory) && ! mkdir($directory, 0755, true) && ! is_dir($directory)) {
            $this->error("Unable to create directory {$directory}.");

            return self::FAILURE;
        }

        file_put_contents($outputPath, $this->generate($baseUrl, $appKey));

        $this->info("✅ Exported Flutter connection config to: {$outputPath}");

        return self::SUCCESS;
    }

    /**
     * Generate the Dart source.
     */
    public function generate(string $baseUrl, ?string $appKey): string
    {
        $prefix = trim((string) config('flutter-bridge.prefix', 'api/flutter'), '/');
        $autoEcho = BroadcastGate::clientOptions() !== null ? 'true' : 'false';

        $lines = [
            '// GENERATED CODE - DO NOT MODIFY BY HAND',
            '// Generated by Laravel Flutter Bridge (php artisan flutter:export-config)',
            '',
            "import 'package:flutter_laravel_bridge/flutter_laravel_bridge.dart';",
            '',
            '/// Default connection profile for this Laravel backend.',
            'const laravelBridgeConfig = LaravelConnection(',
            "  id: 'default',",
            '  name: '.$this->dartString((string) config('app.name', 'Laravel')).',',
            '  baseUrl: '.$this->dartString($baseUrl).',',
            '  prefix: '.$this->dartString($prefix).',',
        ];

        if ($appKey !== null) {
            $lines[] = '  appKey: '.$this->dartString($appKey).',';
        }

        $lines[] = "  autoConfigureEcho: {$autoEcho},";
        $lines[] = ');';
        $lines[] = '';

        return implode("\n", $lines);
    }

    /**
     * Resolve the output file path.
     */
    protected function resolveOutputPath(): string
    {
        $output = $this->option('output')
            ?: rtrim((string) config('flutter-bridge.generator.output_path', '../flutter-laravel-bridge/lib/src/generated'), '/');

        $output = (string) $output;

        if (! Str::startsWith($output, '/')) {
            $output = base_path($output);
        }

        if (! Str::endsWith($output, '.dart')) {
            $output = rtrim($output, '/').'/'.self::FILE_NAME;
        }

        return $output;
    }

    /**
     * Encode a Dart single-quoted string literal.
     */
    protected function dartString(string $value): string
    {
        $escaped = str_replace(
            ['\\', "'", '$', "\n", "\r"],
            ['\\\\', "\\'", '\\$', '\\n', '\\r'],
            $value
        );

        return "'{$escaped}'";
    }
}
